use system.collections.list

fn square_all(xs List<int>) List<int>
    var out = List<int>()
    for x in xs
        out.push(x * x)
    out

fn main()
    let nums = List([1, 2, 3, 4])
    let squares = square_all(nums)
    println(f"squares of {nums.length()} numbers: {squares.reduce(0, fn(a int, b int) int: a + b)} total")

